import { useEffect, useMemo, useState } from "react";
import { HiBanknotes, HiBellAlert, HiBuildingOffice2, HiCheckCircle, HiHomeModern, HiKey, HiMegaphone, HiScale, HiUserCircle } from "react-icons/hi2";
import { useNavigate } from "react-router-dom";
import propertiesPortalService from "@/services/propertiesPortalService";
import PropertiesLogo from "../components/PropertiesLogo";
import "./community-portal.css";

const money=(value,currency="MXN")=>new Intl.NumberFormat("es-MX",{style:"currency",currency}).format(Number(value)||0);
function CommunityPortal(){
  const navigate=useNavigate();const [section,setSection]=useState("home");const [state,setState]=useState({me:null,units:[],statement:null,announcements:[],votes:[],packages:[]});const [loading,setLoading]=useState(true);const [error,setError]=useState("");
  const load=async()=>{if(!propertiesPortalService.hasSession()){navigate("/servicio/login",{replace:true});return}setLoading(true);setError("");try{const [me,units,statement,announcements,votes,packages]=await Promise.all([propertiesPortalService.me(),propertiesPortalService.units(),propertiesPortalService.statement(),propertiesPortalService.announcements(),propertiesPortalService.votes(),propertiesPortalService.packages()]);setState({me,units,statement,announcements,votes,packages})}catch(requestError){if(requestError.response?.status===401){propertiesPortalService.logout();navigate("/servicio/login",{replace:true});return}setError(requestError.response?.data?.error?.message||"No pudimos cargar el portal.")}finally{setLoading(false)}};
  useEffect(()=>{load()},[]);
  const nav=[["home",HiHomeModern,"Mi comunidad"],["charges",HiBanknotes,"Estado de cuenta"],["notices",HiMegaphone,"Comunicados"],["votes",HiScale,"Votaciones"],["packages",HiKey,"Paquetería"]];const title=useMemo(()=>nav.find(([key])=>key===section)?.[2],[section]);const unread=state.announcements.filter(item=>!item.read_at).length;const unit=state.units[0];
  const markRead=async(id)=>{await propertiesPortalService.markAnnouncementRead(id);await load()};const castVote=async(id,optionId)=>{await propertiesPortalService.vote(id,optionId);await load()};
  if(loading)return <main className="community-portal-main"><p>Cargando tu comunidad…</p></main>;
  if(error)return <main className="community-portal-main"><h1>No pudimos abrir el portal</h1><p role="alert">{error}</p><button onClick={load}>Reintentar</button></main>;
  return <div className="community-portal-shell"><aside className="community-portal-nav"><header><PropertiesLogo/><span>PORTAL COMUNIDAD</span></header><nav>{nav.map(([key,Icon,label])=><button type="button" key={key} className={section===key?"active":""} onClick={()=>setSection(key)}><Icon/><span>{label}</span>{key==="notices"&&unread?<i>{unread}</i>:null}</button>)}</nav><footer><span>{state.me?.nombre?.split(" ").slice(0,2).map(word=>word[0]).join("")}</span><div><strong>{state.me?.nombre}</strong><small>{state.me?.email}</small></div><button type="button" onClick={()=>{propertiesPortalService.logout();navigate("/servicio/login")}}><HiUserCircle/></button></footer></aside><main className="community-portal-main"><header><div><small>{unit?.label||"Portal personal"}</small><h1>{title}</h1></div><button className="community-bell"><HiBellAlert/><i>{unread}</i></button></header>
    <section className="community-unit-banner"><div><span>Tus espacios autorizados</span><h2>{unit?.label||"Sin unidades asignadas"}</h2><p>{state.units.length} unidad(es) visibles conforme a tus relaciones y permisos.</p></div><HiBuildingOffice2/></section>
    {section==="home"?<section className="community-pulse"><article><HiBanknotes/><div><small>Saldo actual</small><strong>{money(state.statement?.total_due)}</strong><em>{state.statement?.open_charges?.length||0} cargos abiertos</em></div></article><article><HiMegaphone/><div><small>Comunicados nuevos</small><strong>{unread}</strong><em>{state.announcements.length} publicados</em></div></article><article><HiKey/><div><small>Paquetes pendientes</small><strong>{state.packages.filter(item=>item.status!=="delivered").length}</strong><em>Registrados por recepción</em></div></article></section>:null}
    {section==="charges"?<section className="community-section"><header><div><span>Información personal</span><h2>Estado de cuenta</h2><p>Sólo se muestran cargos asociados a tu persona.</p></div></header><div className="community-list">{state.statement?.open_charges?.map(item=><article key={item.id}><HiBanknotes/><div><strong>{item.concept}</strong><small>Vence {item.due_date} · {item.status}</small></div><b>{money(Number(item.amount)-Number(item.paid_amount),item.currency)}</b></article>)}{!state.statement?.open_charges?.length?<p><HiCheckCircle/> No tienes cargos pendientes.</p>:null}</div></section>:null}
    {section==="notices"?<section className="community-section"><header><div><span>Información oficial</span><h2>Comunicados</h2></div></header><div className="community-list">{state.announcements.map(item=><article key={item.id}><HiMegaphone/><div><strong>{item.title}</strong><small>{item.body}</small></div>{!item.read_at?<button onClick={()=>markRead(item.id)}>Marcar leído</button>:<i className="ok">Leído</i>}</article>)}</div></section>:null}
    {section==="votes"?<section className="community-section"><header><div><span>Participación</span><h2>Votaciones</h2></div></header>{state.votes.map(item=><article className="community-vote" key={item.id}><HiScale/><div><small>{item.status}</small><h3>{item.question}</h3></div>{item.status==="open"?<footer>{item.options.map(option=><button key={option.id} onClick={()=>castVote(item.id,option.id)}>{option.label}</button>)}</footer>:<i>Consulta</i>}</article>)}</section>:null}
    {section==="packages"?<section className="community-section"><header><div><span>Recepción</span><h2>Paquetería</h2></div></header><div className="community-list">{state.packages.map(item=><article key={item.id}><HiKey/><div><strong>{item.carrier||"Paquete"}</strong><small>{item.tracking_number||"Sin guía"} · recibido {new Date(item.received_at).toLocaleString("es-MX")}</small></div><i className={item.status==="delivered"?"ok":"new"}>{item.status==="delivered"?"Entregado":"En recepción"}</i></article>)}</div></section>:null}
    <footer>La información visible depende de tus relaciones y permisos activos.</footer></main></div>;
}
export default CommunityPortal;
